const HOST_MODE=document.body.dataset.mode==='host';
const R=WorkmateRoles;
const W=Workmate,$=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getSaved=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('이 브라우저에서는 자동 저장을 사용할 수 없어요. 코드를 따로 보관해주세요.')}};
const previousParticipant=getSaved('wm-participant-v2',{});
let participant=getSaved('wm-participant-v5',{name:previousParticipant.name||'',role:previousParticipant.role||'',answers:Array(48).fill(null),page:0,scale:5});
if(!participant||!Array.isArray(participant.answers)||participant.answers.length!==48||participant.scale!==5)participant={name:'',answers:Array(48).fill(null),page:0,scale:5};
if(!Number.isInteger(participant.orderSeed)){const seed=new Uint32Array(1);crypto.getRandomValues(seed);participant.orderSeed=seed[0];save('wm-participant-v5',participant);}
let host=getSaved('wm-host-v2',{expected:13,people:[],sealed:false,sample:false});
if(!host||!Array.isArray(host.people)||!host.people.every(W.validProfile))host={expected:13,people:[],sealed:false,sample:false};
let surveyStarted=false,selectedName='',countTimer=null,revealGeneration=0;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function go(hash){if(location.hash===hash)render();else location.hash=hash;}
function persistParticipant(){save('wm-participant-v5',participant)}
function persistHost(){save('wm-host-v2',host)}
function confetti(){const box=$('.match-hero');if(!box||matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<30;i++){const el=document.createElement('i');el.className='confetti';el.style.cssText=`left:${(i*37)%100}%;background:${['#d8ff72','#b7a2ff','#ffb997'][i%3]};animation-delay:${(i%8)*.08}s`;box.append(el);}}
function render(){clearTimeout(countTimer);revealGeneration++;document.querySelector('.reveal-stage')?.remove();let route=location.hash.slice(1);document.documentElement.classList.toggle('home',!route);document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===location.hash));if(!HOST_MODE&&['host','results','guide'].includes(route)){location.replace('index.html');return;}if(HOST_MODE&&!['host','results','guide'].includes(route)){location.hash='#host';return;}if(route==='survey')renderSurvey();else if(route==='complete')renderComplete();else if(route==='host')renderHost();else if(route==='results')renderResults();else if(route==='guide')renderGuide();else renderHome();window.scrollTo(0,0);}
function renderHome(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">OUR WORK, OUR CHEMISTRY</div><h1>일로 만난 우리,<br>의외로 <em>잘 맞을지도.</em></h1><p class="intro">지난 업무 속 나의 선택을 돌아보면<br>사용자와 동료를 향한 나만의 방식이 보여요.<br>채팅탭 스쿼드, 우리의 협업 케미를 발견해볼까요?</p><div class="hero-actions"><a class="btn primary" href="#survey">나의 워크메이트 찾기 <span aria-hidden="true">✦</span></a></div><div class="hero-meta"><span>48개의 작은 선택</span><span>약 10–15분</span><span>정답은 없어요</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="art-caption">BETTER, TOGETHER.</div><div class="mini-profile one"><span class="label">THINK & CONNECT</span><div class="face curly"><i class="hair"></i><i class="smile"></i></div><strong>생각을 잇는 나</strong><small>맥락을 모으고, 함께 정리하고</small></div><div class="mini-profile two"><span class="label">TRY & DISCOVER</span><div class="face round"><i class="hair"></i><i class="smile"></i></div><strong>가능성을 여는 너</strong><small>작게 시도하고, 새롭게 발견하고</small></div><div class="match-badge">✳</div><div class="float-chip a">“초안부터 같이 볼까요?”</div><div class="float-chip b">우리, 이렇게 닮았네요!</div><span class="float-star">✦</span></div></section><section class="process"><div class="lead"><span>HOW WE MEET</span>혼자 답하고,<br>함께 발견하는 시간.</div><div><span class="step-icon">▧</span><strong>지난 업무를 떠올려요</strong><p>이상적인 모습 대신, 실제 일했던<br>나의 방식을 골라주세요.</p></div><div><span class="step-icon">⌘</span><strong>나만의 코드를 전달해요</strong><p>설문을 마치면 응답 코드가 나와요.<br>주최자에게 코드만 전달해주세요.</p></div><div><span class="step-icon">✳</span><strong>우리의 조합을 열어봐요</strong><p>전원 참여 후 함께 결과를 공개해요.<br>이유를 나누면 더 재미있어요.</p></div></section>`;}
function renderSurvey(){if(W.validProfile(participant)&&participant.role&&!surveyStarted){go('#complete');return;}if(!surveyStarted){app.innerHTML=`<section class="page" style="max-width:700px"><div class="eyebrow">MEET YOUR WORKMATE</div><h1>어떤 모습으로<br>함께 일해왔나요?</h1><p class="sub">최근 동료와 일했던 모습을 떠올려주세요.<br>그때 내가 했던 행동을 골라주세요. 정답은 없어요.</p><div class="panel"><label class="field-label" for="nickname">동료들이 알아볼 수 있는 닉네임</label><input class="input" id="nickname" placeholder="예: 올리버" maxlength="20" autocomplete="nickname" value="${esc(participant.name)}"><p class="micro">결과 공개 시 이 이름이 보여요. 서로 다른 닉네임을 사용해주세요.</p><label class="field-label" for="job-role" style="margin-top:22px">주로 하는 일</label><select class="input select" id="job-role"><option value="">직군을 골라주세요</option>${R.roles.map(r=>`<option value="${r.id}" ${participant.role===r.id?'selected':''}>${r.name}</option>`).join('')}</select><p class="micro">익숙한 예시를 보여드릴게요. 매칭은 직군과 상관없이 해요.</p><div class="rule"></div><div class="tag-grid"><div>48문항 · 8가지 협업 관점<small>서로 다른 네 가지 행동 중 하나를 골라요.</small></div><div>약 10–15분 · 자동 저장<small>같은 브라우저에서 이어서 답할 수 있어요.</small></div></div><p class="notice" style="margin-top:20px">응답 코드는 닉네임·선택 직무·답변을 담고 있어요. 주최자에게만 전달해주세요. 이 초안은 서버로 응답을 보내지 않고 현재 브라우저에 저장해요.</p><p id="start-error" class="error" role="alert"></p><button class="btn primary wide" id="begin">${participant.answers.some(Boolean)?'이어서 답하기':'설문 시작하기'}</button></div><p class="micro">네 가지 모두 선택할 수 있는 방법이에요. 실제 내 행동을 떠올려주세요.</p></section>`;$('#begin').onclick=()=>{const name=$('#nickname').value.trim();if(!name){$('#start-error').textContent='닉네임을 입력해주세요.';$('#nickname').focus();return;}const role=$('#job-role').value;if(!R.roles.some(r=>r.id===role)){$('#start-error').textContent='직군을 골라주세요.';$('#job-role').focus();return;}participant.name=name;participant.role=role;persistParticipant();surveyStarted=true;renderSurvey();};return;}
  const page=Math.min(5,Math.max(0,participant.page||0)),start=page*8,answered=participant.answers.filter(Boolean).length;
  app.innerHTML=`<section class="page"><div class="survey-heading"><div class="flex spread"><span class="eyebrow">YOUR WORKING RHYTHM</span><span class="pill">${esc(participant.name)} · ${esc(R.roles.find(r=>r.id===participant.role)?.name||'공통')}</span></div><h1>${['사용자의 문제를 마주할 때','동료와 호흡을 맞출 때','선택의 순간이 왔을 때','나답게 일했던 순간','조금 더 돌아보면','마지막 여덟 가지 선택'][page]}</h1><div class="progress" role="progressbar" aria-label="설문 완료" aria-valuenow="${answered}" aria-valuemin="0" aria-valuemax="48"><span style="width:${answered/48*100}%"></span></div><div class="flex spread micro"><span>${page+1} / 6 페이지</span><span id="answered-count">${answered} / 48 응답</span></div></div><p class="micro">지난 일을 떠올리며, 내가 했던 행동 하나를 골라주세요.</p>${W.questions.slice(start,start+8).map(q=>R.questionFor(q,participant.role,participant.orderSeed)).map(q=>`<section class="question" id="q-${q.id}" aria-labelledby="title-${q.id}"><h2 id="title-${q.id}"><small>${String(q.id+1).padStart(2,'0')}</small>${q.text}</h2><p class="job-example">${esc(q.context)}</p><div class="scale" role="group" aria-label="${esc(q.text)}">${q.options.map(o=>`<button data-q="${q.id}" data-value="${o.id}" class="${participant.answers[q.id]===o.id?'selected':''}" aria-label="${esc(o.text)}" aria-pressed="${participant.answers[q.id]===o.id}"><span class="option-check" aria-hidden="true">${participant.answers[q.id]===o.id?'✓':''}</span><span>${esc(o.text)}</span></button>`).join('')}</div></section>`).join('')}<p id="survey-error" class="error" role="alert"></p><div class="survey-nav"><button id="prev" class="btn ghost">${page===0?'이름·직군 수정':'이전 페이지'}</button><span class="micro">자동 저장 중</span><button id="next" class="btn primary">${page===5?'설문 완료하기':'다음 페이지'}</button></div></section>`;
  document.querySelectorAll('[data-q]').forEach(button=>button.onclick=()=>{const q=+button.dataset.q,v=+button.dataset.value;participant.answers[q]=v;persistParticipant();document.querySelectorAll(`[data-q="${q}"]`).forEach(b=>{const selected=+b.dataset.value===v;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected);b.querySelector('.option-check').textContent=selected?'✓':'';});const n=participant.answers.filter(Boolean).length;$('.progress span').style.width=n/48*100+'%';$('.progress').setAttribute('aria-valuenow',n);$('#answered-count').textContent=`${n} / 48 응답`;$('#survey-error').textContent='';});
  $('#prev').onclick=()=>{if(page===0)surveyStarted=false;else participant.page=page-1;persistParticipant();renderSurvey();window.scrollTo(0,0)};
  $('#next').onclick=()=>{const missing=W.questions.slice(start,start+8).find(q=>!participant.answers[q.id]);if(missing){$('#survey-error').textContent=`${missing.id+1}번 문항을 골라주세요.`;$('#q-'+missing.id).scrollIntoView({behavior:'smooth',block:'center'});$('#q-'+missing.id+' button').focus({preventScroll:true});return;}if(page===5){if(!W.validProfile(participant)){toast('응답하지 않은 문항이 있어요.');return;}persistParticipant();surveyStarted=false;go('#complete')}else{participant.page=page+1;persistParticipant();renderSurvey();window.scrollTo(0,0)}};
}
function renderComplete(){if(!W.validProfile(participant)){go('#survey');return;}const code=W.encode(participant);app.innerHTML=`<section class="page completion"><div class="complete-icon">✓</div><div class="eyebrow" style="justify-content:center">YOUR CODE IS READY</div><h1>${esc(participant.name)}님, 참여 완료!<br>발견은 잠시 뒤, 다 함께.</h1><p class="sub">설문이 모두 완료되면 결과를 볼 수 있어요.<br>아래 코드를 주최자에게 전달해주세요.</p><div class="panel"><div class="flex spread" style="margin-bottom:15px"><span class="field-label" style="margin:0">나의 응답 코드</span><span class="pill lime">48 / 48 완료</span></div><div class="code" id="my-code">${code}</div><button class="btn primary wide" id="copy-code">응답 코드 복사하기</button><p class="micro" style="margin-bottom:0">코드 전체를 복사해 전달해주세요. 이름·선택 직무·응답이 포함되어 있어요.</p></div><p class="sub" style="margin-top:30px">기다리는 동안 생각해보기<br><span style="color:var(--ink)">“최근 나와 호흡이 잘 맞았던 순간은 언제였지?”</span></p><button class="btn ghost small" id="edit-answers">응답 다시 살펴보기</button><p class="micro">답변을 바꿨다면 새 코드를 다시 전달해주세요.</p></section>`;$('#copy-code').onclick=()=>copy(code,'코드를 복사했어요. 주최자에게 전달해주세요.');$('#edit-answers').onclick=()=>{participant.page=0;surveyStarted=true;go('#survey')};}
async function copy(text,msg){try{await navigator.clipboard.writeText(text);toast(msg)}catch{const el=document.createElement('textarea');el.value=text;document.body.append(el);el.select();try{document.execCommand('copy');toast(msg)}catch{toast('복사가 제한되어 있어요. 코드를 직접 선택해 복사해주세요.')}el.remove()}}
function ready(){return host.people.every(p=>p.scale===5)&&Number.isInteger(host.expected)&&host.expected>=2&&host.expected<=100&&host.people.length===host.expected;}
function renderHost(){app.innerHTML=`<section class="page wide"><div class="eyebrow">THE HOST'S DESK</div><div class="flex spread"><div><h1>우리의 코드를 모아볼까요?</h1><p class="sub">전원의 응답 코드를 모으면, 한 명씩 워크메이트를 공개할 수 있어요.</p></div><a class="btn ghost small" href="#guide">60분 진행 가이드</a></div>${host.people.some(p=>p.scale!==5)?'<div class="sample-banner">이전 설문 코드가 있어요. 필요하면 백업한 뒤 초기화하고, 새 설문을 마친 WM5 코드를 모아주세요.</div>':''}${host.sample?'<div class="sample-banner">샘플 모드 · 가상 응답으로 만든 미리보기예요. 실제 참가자 데이터와 섞이지 않아요.</div>':''}<div class="host-grid"><div><section class="panel"><div class="flex spread"><h2>응답 코드 등록</h2><span class="pill">주최자 브라우저에만 저장</span></div><label class="field-label" for="codes">전달받은 코드를 붙여넣어주세요</label><textarea id="codes" class="input" placeholder="WM5.으로 시작하는 새 설문의 코드를 넣어주세요.\n여러 코드는 줄을 바꾸거나 공백으로 구분해 한 번에 넣을 수 있어요." spellcheck="false"></textarea><p id="code-error" class="error" role="alert"></p><div class="flex spread"><span class="micro">닉네임 중복은 등록되지 않아요.</span><button id="add-codes" class="btn primary small">코드 등록하기</button></div></section><section class="panel"><div class="flex spread"><h2 style="margin:0">참여한 멤버</h2><span class="micro">${host.people.length}명 등록됨</span></div><div class="person-list">${host.people.length?host.people.map((p,i)=>`<span class="person-chip">${esc(p.name)} <small class="micro">${esc(R.roles.find(r=>r.id===p.role)?.name||'공통 응답')}</small><button class="remove" data-remove="${i}" aria-label="${esc(p.name)} 코드 제거">×</button></span>`).join(''):'<p class="note-text">아직 도착한 코드가 없어요.<br>아래 샘플로 결과 화면부터 구경해도 좋아요.</p>'}</div><div class="flex"><button id="export" class="btn ghost small" ${host.people.length?'':'disabled'}>코드 백업</button><button id="reset-host" class="btn danger small">취합 데이터 초기화</button></div><p class="micro">백업 파일에는 이름·직무·응답이 들어 있어요. 초기화하면 현재 브라우저의 취합 목록과 공개 상태가 모두 지워져요. 참가자의 설문과 내려받은 백업은 유지돼요.</p></section></div><aside><section class="panel"><h2>모두 모였나요?</h2><label class="field-label" for="expected">이번 워크숍 참가 인원</label><input class="input" id="expected" type="number" min="2" max="100" value="${host.expected}"><div class="big-number">${host.people.length}<small> / <span id="expected-text">${host.expected}</span>명</small></div><p id="ready-note" class="note-text">${ready()?'전원의 코드가 모였어요. 함께 공개할 준비가 됐나요?':'설정한 인원수와 등록된 코드 수가 같아야 공개할 수 있어요.'}</p><label class="check-line"><input id="all-done" type="checkbox" ${host.sealed?'checked':''} ${ready()?'':'disabled'}><span>실제 참가자 전원이 설문을 마쳤고, 코드를 모두 등록했어요.</span></label><button id="open-results" class="btn primary wide" ${ready()&&host.sealed?'':'disabled'}>워크메이트 공개하기 ✦</button></section><div class="notice" style="margin-top:18px">전원 완료 여부는 주최자가 확인해요. 참가자 휴대폰과 자동으로 연결되지는 않아요.</div><button id="sample" class="btn ghost wide" style="margin-top:15px">가상 멤버 6명으로 미리보기</button><p class="micro">‘잘 맞는 사람’은 각자의 응답 기준이에요. 서로를 1명씩 독점 배정하지 않아 같은 동료가 여러 번 등장할 수 있어요.</p></aside></div></section>`;
  $('#expected').onchange=e=>{const n=+e.target.value;if(!Number.isInteger(n)||n<2||n>100){toast('참가 인원은 2~100명으로 입력해주세요.');e.target.value=host.expected;return;}host.expected=n;host.sealed=false;persistHost();renderHost()};
  $('#add-codes').onclick=()=>{const raw=$('#codes').value.trim();if(!raw){$('#code-error').textContent='코드를 먼저 붙여넣어주세요.';return;}if(host.sample){$('#code-error').textContent='샘플을 비운 뒤 실제 코드를 등록해주세요.';return;}const tokens=raw.split(/\s+/).filter(Boolean),pending=[],errors=[];for(let i=0;i<tokens.length;i++){try{const p=W.decode(tokens[i]);if(p.scale!==5)throw Error('질문과 답변을 새로 만들었어요. 새 설문을 마친 WM5 코드가 필요해요.');if([...host.people,...pending].some(x=>x.name.normalize('NFKC').toLocaleLowerCase()===p.name.normalize('NFKC').toLocaleLowerCase()))throw Error(`${p.name}: 이미 등록된 닉네임이에요. 수정 응답이라면 기존 코드를 먼저 제거해주세요.`);pending.push(p)}catch(e){errors.push(`${i+1}번째 코드: ${e.message}`)}}if(errors.length){$('#code-error').textContent=errors.join(' ');return;}if(host.people.length+pending.length>host.expected){$('#code-error').textContent='등록 후 인원이 참가 인원보다 많아져요. 참가 인원을 확인해주세요.';return;}host.people.push(...pending);host.sealed=false;persistHost();renderHost();toast(`${pending.length}명의 코드를 등록했어요.`)};
  document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{host.people.splice(+b.dataset.remove,1);host.sealed=false;persistHost();renderHost()});
  $('#all-done').onchange=e=>{host.sealed=e.target.checked;persistHost();$('#open-results').disabled=!(ready()&&host.sealed)};
  $('#open-results').onclick=()=>{if(ready()&&host.sealed){selectedName=host.people[0].name;go('#results')}};
  $('#sample').onclick=loadDemo;
  $('#reset-host').onclick=openResetDialog;
  $('#export').onclick=()=>download('워크메이트_응답코드.txt',host.people.map(W.encode).join('\n'));
}
function loadDemo(){if(host.people.length&&!host.sample){toast('실제 코드가 등록되어 있어요. 백업 후 초기화하면 샘플을 볼 수 있어요.');go('#host');return;}
  const seeds=[['모모',[1,2,3,1,3,2,1,1]],['루카',[1,2,3,1,3,2,4,4]],['누리',[4,4,1,4,2,4,4,4]],['도담',[4,4,1,4,2,4,1,1]],['보리',[2,1,4,2,4,2,1,3]],['유자',[2,1,4,2,4,2,4,1]]];
  host={expected:6,sealed:true,sample:true,people:seeds.map(([name,values],p)=>({name,role:['pm','dev','design','pm','dev','design'][p],scale:5,answers:W.questions.map(q=>Math.min(4,values[q.dim]+((q.id+p*2)%11===0?1:0)))}))};selectedName=host.people[0].name;persistHost();go('#results');
}
function personOptions(){return host.people.map(p=>`<option value="${esc(p.name)}" ${p.name===selectedName?'selected':''}>${esc(p.name)}</option>`).join('')}
function renderResults(){if(!ready()||!host.sealed){go('#host');return;}const person=host.people.find(p=>p.name===selectedName)||host.people[0];selectedName=person.name;app.innerHTML=`<section class="page wide"><div class="flex spread"><div><div class="eyebrow">LET'S FIND YOUR CHEMISTRY</div><h1>다음 워크메이트는 누구?</h1></div><a class="btn ghost small" href="#host">코드 목록으로</a></div>${host.sample?'<div class="sample-banner">가상 멤버의 샘플 응답입니다. 실제 팀원의 결과가 아니에요.</div>':''}<div class="panel" style="text-align:center;padding:50px 25px"><p class="sub" style="margin:0 0 22px">함께 화면을 보고, 오늘의 주인공을 골라주세요.</p><select class="select" id="reveal-person" aria-label="결과를 공개할 멤버">${personOptions()}</select><div style="font-size:65px;color:var(--lilac);margin:26px 0">✳</div><h2 style="font-size:26px;margin:0 0 12px">나와 가장 잘 맞는 사람은…!</h2><p class="sub">내가 골랐던 작은 선택들이<br>어떤 동료와 이어질지 확인해보세요.</p><button class="btn primary" id="reveal" style="margin-top:17px">두근두근, 공개하기</button><p class="micro" style="margin-top:18px">약 5초의 연출 뒤 결과가 나와요. 애니메이션을 건너뛸 수도 있어요.</p></div><details style="margin-top:25px"><summary>매칭은 어떻게 하나요?</summary><p>최근 업무 선택 48개를 8개 관점으로 묶습니다. 함께 일하는 리듬 6개 관점의 유사도 85%와, 협업 기여 방식 2개 관점의 차이 15%를 합산합니다. 역할의 차이는 분담 가능성을 살펴보는 가정이며, 차이가 클수록 실제 협업이 좋다는 뜻은 아닙니다. 점수는 이 워크숍 안에서 응답을 비교하는 참고값이며 검증된 심리검사나 성과 예측값이 아닙니다. 동점은 닉네임 순으로 표시하고 결과에 동점을 알립니다.</p></details></section>`;$('#reveal-person').onchange=e=>selectedName=e.target.value;$('#reveal').onclick=animateReveal;}
function animateReveal(){const person=host.people.find(p=>p.name===selectedName);if(!person)return;const generation=++revealGeneration;let done=false;const finish=()=>{if(done||generation!==revealGeneration)return;done=true;clearTimeout(countTimer);$('.reveal-stage')?.remove();showMatch(person)};const stage=document.createElement('div');stage.className='reveal-stage';stage.setAttribute('role','dialog');stage.setAttribute('aria-modal','true');stage.setAttribute('aria-label','워크메이트 공개');stage.innerHTML=`<div class="reveal-spark" aria-hidden="true"></div><span class="eyebrow">THE MOMENT OF CHEMISTRY</span><h1>${esc(person.name)}님과<br>가장 잘 맞는 사람은…!</h1><div class="reveal-count" aria-live="polite">✦</div><p class="reveal-note">우리의 선택이 이어지는 순간</p><button class="btn ghost small reveal-skip">바로 결과 보기</button>`;document.body.append(stage);stage.querySelector('button').onclick=finish;stage.querySelector('button').focus();if(matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return;}let n=3;function tick(){if(generation!==revealGeneration)return;if(n===0){finish();return;}const old=stage.querySelector('.reveal-count'),el=old.cloneNode(false);el.textContent=n--;old.replaceWith(el);countTimer=setTimeout(tick,1000);}countTimer=setTimeout(tick,1000);}
function selectedAnswer(q,p){return R.questionFor(q,p.role).options.find(o=>o.id===p.answers[q.id]).text;}
function sharedAnswer(q,a,b){const x=selectedAnswer(q,a),y=selectedAnswer(q,b);return x===y?`두 분 모두 <strong>“${esc(x)}”</strong>를 골랐어요.`:`같은 뜻의 행동을 골랐어요.<br>${esc(a.name)}: ${esc(x)}<br>${esc(b.name)}: ${esc(y)}`;}
function showMatch(person){if(!ready()||!host.sealed){go('#host');return;}const ranks=W.ranking(person,host.people),best=ranks[0],mate=best.person,ev=W.evidence(person,mate),tied=ranks.filter(r=>r.score===best.score).length>1;const role=ev.role,rsA=best.a[role.dim],rsB=best.b[role.dim];
  app.innerHTML=`<section class="page wide"><div class="flex spread"><a href="#host" class="btn ghost small">주최자 모드</a><select class="select" id="next-person" aria-label="다음 공개할 멤버">${personOptions()}</select></div>${host.sample?'<div class="sample-banner">샘플 결과 · 가상 멤버의 응답으로 만든 미리보기예요.</div>':''}<section class="match-hero"><span class="score"><b>${best.score}</b>응답 조합 점수</span><div class="eyebrow">YOUR WORKMATE IS</div><h1>${esc(mate.name)}님입니다!</h1><p class="match-kicker">작은 선택 속에서 발견한, 함께 일하는 방식의 공통점.</p><div class="match-people"><div><div class="avatar">${esc([...person.name].slice(0,2).join(''))}</div><strong>${esc(person.name)}</strong></div><span class="match-connector">✳</span><div><div class="avatar alt">${esc([...mate.name].slice(0,2).join(''))}</div><strong>${esc(mate.name)}</strong></div></div><p class="micro">${tied?'최고 점수가 같은 멤버가 있어요. 아래에서 동점 멤버도 함께 확인해주세요.':'함께 일하는 리듬 85% + 협업 기여 방식의 균형 15%'}<br>이 점수는 응답 비교값이에요. 실제 관계나 업무 성과를 예측하지 않아요.</p></section><div class="results-grid"><div><section class="panel"><h2>이런 점이 닮았어요</h2><p class="micro">두 사람이 실제로 고른 행동을 함께 살펴봐요.</p>${ev.same.map(q=>`<div class="evidence"><span class="evidence-label">같은 선택 · ${q.id+1}번</span><p class="micro">${esc(W.values.find(v=>v.id===q.value).text)}</p><p class="q">${q.text}</p><p>${sharedAnswer(q,person,mate)}</p></div>`).join('')}${ev.close.map(q=>`<div class="evidence"><span class="evidence-label">서로 다른 선택 · ${q.id+1}번</span><p class="micro">${esc(W.values.find(v=>v.id===q.value).text)}</p><p class="q">${q.text}</p><p>${esc(person.name)}: ${esc(selectedAnswer(q,person))}<br>${esc(mate.name)}: ${esc(selectedAnswer(q,mate))}</p></div>`).join('')}</section><section class="panel"><h2>다르니까, 나눠볼 이야기</h2><p class="note-text">${role.gap>=1?`‘${role.name}’에서 ${esc(person.name)}님은 ‘${rsA<3?role.left:role.right}’, ${esc(mate.name)}님은 ‘${rsB<3?role.left:role.right}’ 쪽 응답이 더 많았어요. 다음 과제에서 역할을 나눠볼 단서가 될 수 있어요.`:'협업 기여 방식도 비교적 비슷하게 답했어요. 억지로 반대 역할을 맡기기보다, 각자 맡고 싶은 구간을 먼저 물어보면 좋겠어요.'}</p><div class="notice">${ev.gap.gap>=1?`‘${ev.gap.name}’는 두 사람의 응답 차이가 가장 큰 리듬이에요. 시작 전에 어떤 방식으로 맞추면 좋을지 이야기해보세요.`:'협업 리듬은 전반적으로 비슷했어요. 같은 답을 골랐어도 떠올린 상황은 다를 수 있으니 실제 사례를 나눠보세요.'}</div></section></div><div><section class="panel"><h2>나란히 보면 이런 모습</h2><div class="legend"><span><i></i>${esc(person.name)}</span><span><i class="alt"></i>${esc(mate.name)}</span></div>${W.dimensions.map((d,i)=>`<div class="bar-pair"><div class="dim-title"><span>${d.name}</span><span>${i<6?'리듬':'기여'}</span></div><div class="bar-track"><i class="dot" style="left:${5+(best.a[i]-1)/4*90}%"></i><i class="dot alt" style="left:${5+(best.b[i]-1)/4*90}%"></i></div><div class="bar-labels"><span>${d.left}</span><span>${d.right}</span></div></div>`).join('')}</section><section class="panel"><h2>이제, 서로에게 물어보기</h2><p class="discussion">“같은 답을 골랐는데,<br>어떤 업무가 떠올랐어요?”</p><p class="discussion">“우리 다음에 같이 일한다면,<br>무엇부터 맞추면 좋을까요?”</p><p class="micro">두 사람씩 4분 이야기하고, 의외였던 점 하나를 나눠주세요.</p></section></div></div><section class="panel"><h2>${esc(person.name)}님의 다른 연결</h2><p class="micro">개인별 비교라 같은 멤버가 여러 번 나올 수 있어요. 동점은 닉네임 순으로 표시해요.</p><table class="roster-table"><thead><tr><th>멤버</th><th>조합 점수</th><th>리듬 유사도</th><th>비교</th></tr></thead><tbody>${ranks.slice(0,3).map(r=>`<tr><td>${esc(r.person.name)} ${r.score===best.score&&tied?'<span class="pill">공동 최고</span>':''}</td><td>${r.score}</td><td>${r.shared}%</td><td><button data-compare="${esc(r.person.name)}">이 멤버 차례 보기</button></td></tr>`).join('')}</tbody></table></section><div class="results-actions"><button class="btn primary" id="replay">한 번 더 공개하기 ✦</button><button class="btn ghost" id="back-selection">다음 멤버 고르기</button></div><details><summary>점수와 근거를 읽는 방법</summary><p>선택한 행동을 질문별로 정한 협업 특성에 연결하며, 각 관점은 관련 문항 6개의 평균입니다. 화면에 보이는 선택지 순서는 점수 순서가 아니며, 각 참가자 안에서는 일정하게 유지됩니다. 리듬 점수는 6개 관점에서 평균 차이가 작을수록 높고, 역할 점수는 2개 관점의 차이가 클수록 높습니다. 최종 점수는 리듬 × 0.85 + 역할 × 0.15입니다. 역할 차이는 분담 가능성을 살펴보기 위한 가정이며 능력이나 협업 성과를 뜻하지 않습니다. 비슷한 응답이 많으면 결과를 충분히 구분하기 어려울 수 있어요. 같은 선택은 같은 행동 ID에서, 차이는 관점 평균에서 가져옵니다. 직군에 맞게 예시가 다른 경우에도 같은 뜻의 행동끼리 비교합니다. 점수는 워크숍 대화를 위한 참고값이고 진단이나 평가에 사용하지 않습니다.</p></details></section>`;
  $('#next-person').onchange=e=>{selectedName=e.target.value;renderResults();window.scrollTo(0,0)};$('#replay').onclick=animateReveal;$('#back-selection').onclick=()=>{renderResults();window.scrollTo(0,0)};document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{selectedName=b.dataset.compare;renderResults();window.scrollTo(0,0)});confetti();window.scrollTo(0,0);
}
function renderGuide(){app.innerHTML=`<section class="page wide"><div class="eyebrow">ONE HOUR, BETTER TOGETHER</div><h1>60분을, 서로를 알아가는 시간으로.</h1><p class="sub">설문은 출발점이에요. 결과보다 ‘왜 그 답을 골랐는지’를 나누는 데 시간을 더 써보세요.</p><div class="guide-grid"><section class="panel"><div class="time">05 <small>min</small></div><h2>가볍게 시작하기</h2><p class="note-text">정답이 없는 선택이라는 점을 안내해요. 최근 함께 일했던 순간 한 가지를 떠올리며 시작해요.</p></section><section class="panel"><div class="time">15 <small>min</small></div><h2>설문과 코드 모으기</h2><p class="note-text">48문항을 각자 답하고 코드를 주최자에게 보내요. 주최자는 참가 인원을 설정하고 전원의 코드를 등록해요.</p></section><section class="panel"><div class="time">15 <small>min</small></div><h2>워크메이트 공개</h2><p class="note-text">한 명씩 카운트다운과 함께 공개해요. 13명 기준 한 사람당 약 1분. 같은 응답 한 가지를 함께 읽어봐요.</p></section><section class="panel"><div class="time">15 <small>min</small></div><h2>사례로 대화하기</h2><p class="note-text">2~3명씩 모여 4분씩 사례를 나눠요. 매칭이 겹치면 세 명이 함께하거나 두 번 자리를 바꿔도 좋아요.</p></section><section class="panel"><div class="time">07 <small>min</small></div><h2>의외의 발견 공유</h2><p class="note-text">‘같은 답, 다른 이유’ 또는 ‘다르지만 맞춰볼 방법’을 각 그룹에서 하나씩 소개해요.</p></section><section class="panel"><div class="time">03 <small>min</small></div><h2>다음 업무에 남기기</h2><p class="note-text">서로 일하기 편해질 작은 약속 하나를 적어요. 예: 초안 공유 전에 확인할 질문을 함께 남기기.</p></section></div><section class="panel"><h2>주최자 준비 메모</h2><ul class="plain-list"><li>참가자는 설문 링크만 받으면 돼요. 응답 코드를 개인 메시지로 모아주세요.</li><li>이 초안은 서버 없는 방식입니다. 참가자가 주최자에게 보낸 코드를 수동으로 모아야 해요.</li><li>주최자 페이지는 별도 링크로 열어요. 링크 분리는 로그인 인증이 아니에요. 코드를 가진 사람이 응답을 확인할 수 있으므로 코드 전체는 공개하지 마세요.</li><li>주최자 컴퓨터에서 결과를 공개하세요. 참가자의 완료 화면은 자동으로 바뀌지 않아요.</li><li>닉네임이 같으면 구분할 수 없어요. 동명이인은 서로 다른 닉네임으로 참여해주세요.</li><li>응답을 수정한 사람은 새 코드를 보내고, 주최자는 이전 코드를 제거한 뒤 다시 등록해요.</li><li>끝나면 필요한 기록만 남기고 ‘취합 데이터 초기화’로 취합 목록과 공개 상태를 지워주세요.</li></ul></section><section class="panel"><h2>카카오가 일하는 법을 담은 48개의 상황</h2><p class="note-text">사용자가 제공한 원칙을 바탕으로 문항을 구성했어요. 어느 답이 원칙을 더 잘 지키는지가 아니라, 같은 원칙을 실천할 때의 접근·소통·협업 방식을 비교합니다. 공식 평가나 인증 설문은 아니에요.</p><div class="tag-grid">${W.values.map(v=>`<div>${esc(v.text)}<small>${W.questions.filter(q=>q.value===v.id).length}개 상황에 반영</small></div>`).join('')}</div></section><section class="panel"><h2>매칭의 약속</h2><p class="note-text">직무 선택은 질문의 상황과 표현에만 쓰여요. 직무·직급·같은 직군 여부는 점수와 순위에 사용하지 않으며, 전원의 응답을 같은 8가지 협업 관점으로 비교해요.</p><p class="note-text">이 결과는 동료의 능력·성격·성과를 평가하지 않아요. ‘최근 업무에서 내가 고른 선택’끼리의 비교입니다. 닮은 리듬은 함께 맞출 지점으로, 다른 협업 기여 방식은 분담을 이야기할 단서로 사용해요. 맞지 않는 결과가 나왔다면 실제 경험을 이야기하며 설명을 더해보세요.</p></section><div class="results-actions"><a href="#host" class="btn primary">주최자 모드로</a><a href="index.html#survey" class="btn ghost">참가자 설문 열기</a></div></section>`;}

function openResetDialog(){
  const dialog=document.createElement('dialog');dialog.className='reset-dialog';
  dialog.innerHTML=`<h2>취합 데이터를 초기화할까요?</h2><p class="note-text">등록된 ${host.people.length}명의 이름·직무·응답 코드, 참가 인원 설정, 전원 완료 확인과 결과 공개 상태를 이 브라우저에서 지워요.</p><div class="notice">참가자가 작성한 설문과 이미 내려받은 백업 파일은 지우지 않아요. 취합 결과가 필요하다면 먼저 백업해주세요.</div><div class="flex" style="justify-content:flex-end;margin-top:24px"><button class="btn ghost small" id="cancel-reset">돌아가기</button><button class="btn danger small" id="confirm-reset">초기화하기</button></div>`;
  document.body.append(dialog);dialog.showModal();
  const close=()=>{dialog.close();dialog.remove();};
  dialog.querySelector('#cancel-reset').onclick=close;
  dialog.addEventListener('cancel',()=>dialog.remove(),{once:true});
  dialog.querySelector('#confirm-reset').onclick=()=>{
    clearTimeout(countTimer);revealGeneration++;selectedName='';document.querySelector('.reveal-stage')?.remove();
    for(const key of ['wm-host','wm-host-v2']){try{localStorage.removeItem(key)}catch{}}
    host={expected:13,people:[],sealed:false,sample:false};persistHost();close();renderHost();toast('취합 데이터와 공개 상태를 초기화했어요.');
  };
  dialog.querySelector('#cancel-reset').focus();
}

function download(filename,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.addEventListener('hashchange',render);render();
